# Load all grids
import os
import re
import json

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
session_dir = d
task_ids_dir = os.path.join(os.environ.get('PLAY_DIR', '/home/USER/runs/paper/qwen-hpl0-u1-turns/frozen/seen-reference-2/play/users/u033'), 'workspace')
programs_dir = os.path.join(task_ids_dir, 'programs')

# Load session history
t = open(os.path.join(session_dir, '../../sessions/', os.path.basename(session_dir) + '.jsonl')).read().replace('\\n', '\n')
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

# Transform function
def transform(grid):
    if not grid:
        return grid
    rows = len(grid)
    cols = len(grid[0])
    result = [[0] * cols for _ in range(rows)]

    # Copy input first
    for r in range(rows):
        for c in range(cols):
            result[r][c] = grid[r][c]

    # Apply horizontally: if grid[r][c-1] == 3 and grid[r][c+1] == 3, set to 2
    for r in range(rows):
        for c in range(1, cols-1):
            if result[r][c] == 9 and result[r][c-1] == 3 and result[r][c+1] == 3:
                result[r][c] = 2

    # Then vertically: if grid[r-1][c] == 3 and grid[r+1][c] == 3, set to 2
    for c in range(cols):
        for r in range(1, rows-1):
            if result[r][c] == 9 and result[r-1][c] == 3 and result[r+1][c] == 3:
                result[r][c] = 2

    return result

# Verify against demo pair
demo_input = G.get('Demo pair 1 input')
demo_output = G.get('Demo pair 1 output')
test_input = G.get('Test input')

if demo_output is None or test_input is None:
    print("Warning: missing grids")
    if demo_output is None:
        print("Need to load more demos")
if demo_output and test_input:
    predicted = transform(demo_input)
    matches = (predicted == demo_output)
    print(f"Transform matches demo: {matches}")
    if not matches:
        for r in range(len(predicted)):
            for c in range(len(predicted[0])):
                if predicted[r][c] != demo_output[r][c]:
                    print(f"Mismatch at ({r},{c}): pred={predicted[r][c]}, demo={demo_output[r][c]}")
    if test_input:
        output = transform(test_input)
        print(f"Test output:\n{json.dumps(output)}")
    else:
        print("Test input not available in session - need to submit first")

